import matplotlib.pyplot as plt
import numpy as np
import imageio.v2 as imageio
import os

# 1. Check if the trajectory data exists
csv_file = 'trajectory_poses.csv'
if not os.path.exists(csv_file):
    print(f"Error: '{csv_file}' not found. Please run your C++ executable first to generate the data!")
    exit(1)

# 2. Load the trajectory data generated by C++
data = np.loadtxt(csv_file, delimiter=',', skiprows=1)
if data.ndim == 1:
    data = np.array([data])

# Extract position and orientation columns
xs = data[:, 1]
ys = data[:, 2]
zs = data[:, 3]
yaws = data[:, 6]

# 3. Set up the 3D plot figure window
fig = plt.figure(figsize=(9, 6))
ax = fig.add_subplot(projection='3d')

frames = []
temp_filename = 'temp_traj_frame.png'

print("Rendering 3D motion animation frames...")

# 4. Loop through each time step to show actual physical movement
for i in range(len(data)):
    ax.clear()
    
    # Draw the path trail up to the current step
    ax.plot(xs[:i+1], ys[:i+1], zs[:i+1], color='gray', linestyle='--', linewidth=1.5, label='Path Traveled')
    
    # Plot the current position marker
    x, y, z, yaw = xs[i], ys[i], zs[i], yaws[i]
    ax.scatter(x, y, z, color='red', s=140, label='Robot Position')
    
    # Draw a heading arrow showing the orientation vector at this step
    dx = np.cos(yaw) * 0.6
    dy = np.sin(yaw) * 0.6
    ax.quiver(x, y, z, dx, dy, 0.0, color='blue', normalize=True, linewidth=2, label='Heading')
    
    # Lock graph boundaries so the scene stays stable during playback
    ax.set_xlim([np.min(xs) - 0.5, np.max(xs) + 0.5])
    ax.set_ylim([np.min(ys) - 1.0, np.max(ys) + 1.0])
    ax.set_zlim([0, np.max(zs) + 1.0])
    
    ax.set_xlabel('X Axis (Forward/Back)')
    ax.set_ylabel('Y Axis (Left/Right)')
    ax.set_zlabel('Z Axis (Up/Down)')
    ax.set_title(f'Velocity Kinematics - Motion Trajectory (Step {i+1}/{len(data)})')
    ax.legend(loc='upper left')
    
    # Save the current frame to a temporary image file
    plt.savefig(temp_filename, dpi=100, format='png')
    frames.append(imageio.imread(temp_filename))

# Clean up temporary frame file
if os.path.exists(temp_filename):
    os.remove(temp_filename)

# 5. Compile all captured frames into an animated GIF
output_gif = 'robot_trajectory.gif'
imageio.mimsave(output_gif, frames, fps=8)
print(f"Success! Motion animation saved as '{output_gif}' in your project folder.")